using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using TransPort.Web.Models;using TransPort.Web.Services;
namespace TransPort.Web.Areas.Gestion.Controllers;
[Area("Gestion"),Authorize(Roles="AdministradorGeneral,Gerente,Empleado,Operativo"),Route("gestion/transportes")]
public sealed class TransportesController(ITransportApiClient api):Controller
{[HttpGet("")]public async Task<IActionResult>Index(string?estado,string?tipo,int?sedeId,CancellationToken ct)=>View(new TransportePaginaViewModel{Estado=estado,Tipo=tipo,SedeId=sedeId,Viajes=await api.TransportesAsync(estado,tipo,sedeId,ct),Opciones=await api.TransporteOpcionesAsync(ct)});[HttpPost("vehiculos")]public async Task<IActionResult>Vehiculo(TransporteVehiculoCrearViewModel m,CancellationToken ct){await api.CrearVehiculoTransporteAsync(m,ct);return RedirectToAction(nameof(Index));}[HttpPost("conductores")]public async Task<IActionResult>Conductor(TransporteConductorCrearViewModel m,CancellationToken ct){await api.CrearConductorTransporteAsync(m,ct);return RedirectToAction(nameof(Index));}[HttpPost("viajes")]public async Task<IActionResult>Viaje(TransporteViajeCrearViewModel m,CancellationToken ct){var id=await api.CrearViajeTransporteAsync(m,ct);return RedirectToAction(nameof(Detalle),new{id});}[HttpGet("{id:long}")]public async Task<IActionResult>Detalle(long id,CancellationToken ct){var x=await api.TransporteAsync(id,ct);return x is null?NotFound():View(x);}[HttpPost("{id:long}/estado")]public async Task<IActionResult>Estado(long id,string estado,string?observacion,CancellationToken ct){await api.EstadoViajeTransporteAsync(id,estado,observacion,ct);return RedirectToAction(nameof(Detalle),new{id});}[HttpPost("{id:long}/incidencias")]public async Task<IActionResult>Incidencia(long id,string tipo,string severidad,string descripcion,CancellationToken ct){await api.CrearIncidenciaTransporteAsync(id,tipo,severidad,descripcion,ct);return RedirectToAction(nameof(Detalle),new{id});}[HttpPost("{id:long}/incidencias/{incidenciaId:long}")]public async Task<IActionResult>Resolver(long id,long incidenciaId,string resolucion,CancellationToken ct){await api.ResolverIncidenciaTransporteAsync(incidenciaId,resolucion,ct);return RedirectToAction(nameof(Detalle),new{id});}[HttpPost("{id:long}/eliminar"),Authorize(Roles="AdministradorGeneral")]public async Task<IActionResult>Eliminar(long id,CancellationToken ct){await api.EliminarViajeTransporteAsync(id,ct);return RedirectToAction(nameof(Index));}}
